from collections import Counter
def transform(grid):
    h, w = len(grid), len(grid[0])
    hr = [(r, Counter(grid[r]).most_common(1)[0][0]) for r in range(h) if Counter(grid[r]).most_common(1)[0][1] > w//2 and Counter(grid[r]).most_common(1)[0][0] != 0]
    vc = [(c, Counter(grid[r][c] for r in range(h)).most_common(1)[0][0]) for c in range(w) if Counter(grid[r][c] for r in range(h)).most_common(1)[0][1] > h//2 and Counter(grid[r][c] for r in range(h)).most_common(1)[0][0] != 0]
    def picks(lines, n):
        out=[]; prev=-1
        for pos, _ in lines:
            if prev + 1 < pos: out.append(prev + 1)
            out.append(pos); prev=pos
        if prev < n-1: out.append(prev+1)
        return out
    return [[grid[r][c] for c in picks(vc,w)] for r in picks(hr,h)]
